    transition: filter var(--ds-dur) var(--ds-ease);
  }
  #services .svc-rows.md-on > .md-ghost .md-ghost__media {
    display: block;
    align-self: stretch;
    min-height: 100%;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
  }
  #services .svc-rows.md-on > .md-ghost .md-ghost__name {
    display: block;
    padding-right: var(--ds-space-md);
    font-family: var(--ds-font-display);
    font-size: 15px;
    line-height: 1.25;
    color: var(--ds-ink);
    overflow-wrap: anywhere;
  }
}

